export type DiffComparison = "uncommitted" | "staged" | "unstaged" | { "branch": string | null } | { "commit": string } | { "between": { base: string, target: string, } } | "lastTurn";
export type DiffChangesRequest = { scope: DraftAttachmentScope, viewId: string, comparison: DiffComparison, };
export type DiffReference = { reference: string, label: string, };
export type DiffReferences = { upstream: string | null, branches: Array<DiffReference>, commits: Array<DiffReference>, };
export type DiffFileView = { fileId: string, path: string, renamedFrom: string | null, };
export type DiffPatchRequest = { scope: DraftAttachmentScope, fileId: string, };
export type DiffSide = "before" | "after";
export type DiffRichKind = "markdown" | "svg" | "pdf" | "raster";
export type DiffContentView = { side: DiffSide, path: string, rich: DiffRichKind | null, text: string | null, editors: Array<FileEditor>, };
export type DiffPatchView = { fileId: string, text: string, exportable: boolean, reviewed: boolean, reviewedHunks: Array<number>, contents: Array<DiffContentView>, };
export type DiffMarkerRequest = { target: DiffPatchRequest, hunk: number | null, reviewed: boolean, };
export type DiffMediaRequest = { target: DiffPatchRequest, side: DiffSide, };
export type DiffAction = "copyPatch" | "exportPatch" | { "exportFile": DiffSide } | { "openEditor": { side: DiffSide, editor: string, } };
export type DiffActionRequest = { target: DiffPatchRequest, action: DiffAction, };
export type LastTurnView = { turnId: string, revision: string | null, quality: TurnEditQuality, totals: EditTotals | null, };
export type EditTotals = { additions: number, deletions: number, };
export type TurnEditQuality = "missing" | "exact" | "reported";
export type QuitView = { ticket: string, confirm: boolean, draining: boolean, stopOnly: boolean, fileAction: FileQuitAction | null, };
export type QuitDecision = { ticket: string, };
